#include <bits/stdc++.h>
using namespace std; using E=pair<int,int>; const int n=9,m=36;
bool conn(const vector<E>&a,uint64_t mask){uint16_t info[9]={1,2,4,8,16,32,64,128,256};for(int i=0;i<m;i++)if(mask>>i&1){auto [u,v]=a[i];info[u]|=info[v];info[v]=info[u];}for(int i=0;i<n;i++)if(info[i]!=511)return false;return true;}
int main(int argc,char**argv){int count=argc>1?atoi(argv[1]):1000000;mt19937 rng(1927);vector<E> base;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)base.emplace_back(i,j);long long tested=0;int maxdeg=0,maxedges=0;for(int z=0;z<count;z++){auto a=base;if(z%2){int sw=1+rng()%20;for(int t=0;t<sw;t++)swap(a[rng()%m],a[rng()%m]);}else shuffle(a.begin(),a.end(),rng);uint64_t full=(1ULL<<m)-1;uint16_t adj[9]={};int edges=0;for(int i=0;i<m;i++)if(!conn(a,full^(1ULL<<i))){auto[u,v]=a[i];adj[u]|=1<<v;adj[v]|=1<<u;edges++;}maxedges=max(maxedges,edges);int alive=511,d=0;while(alive){int vmin=-1,kmin=99;for(int v=0;v<n;v++)if(alive>>v&1){int k=__builtin_popcount((unsigned)(adj[v]&alive));if(k<kmin){kmin=k;vmin=v;}}d=max(d,kmin);alive^=1<<vmin;}if(d>maxdeg){maxdeg=d;cerr<<"maxcore "<<maxdeg<<" trial "<<z<<" forced "<<edges<<"\n";}if(d>=3){cout<<"COUNTEREXAMPLE d="<<d<<" edges="<<edges<<"\n";for(auto [u,v]:a)cout<<u<<" "<<v<<"\n";return 0;}tested++;}cout<<"tested "<<tested<<" maxcore "<<maxdeg<<" maxforced "<<maxedges<<"\n";}
